type Sinal<T> = T extends number ? "numero" : "outro";

const conhecido: Sinal<number> = "numero";
const tambemConhecido: Sinal<string> = "outro";
console.log(conhecido, tambemConhecido); // numero outro

function rotular<T>(valor: T): Sinal<T> {
  // @ts-expect-error com T por resolver, Sinal<T> não aceita nenhum dos dois ramos
  return typeof valor === "number" ? "numero" : "outro";
}

const a = rotular(10);    // a: "numero"
const b = rotular("dez"); // b: "outro"
const provaA: "numero" = a;
const provaB: "outro" = b;
console.log(provaA, provaB); // numero outro

