type SoTexto<T> = T extends string ? true : false;            // distribui
type SoTextoInteiro<T> = [T] extends [string] ? true : false; // testa a união inteira

type A = SoTexto<string | number>;        // true | false, ou seja boolean
type B = SoTextoInteiro<string | number>; // false
type C = SoTextoInteiro<"a" | "b">;       // true

const a1: A = true;
const a2: A = false;
const b1: B = false;
// @ts-expect-error B resolve para false e mais nada
const b2: B = true;
const c1: C = true;

type Vazio = SoTexto<never>; // never: a união vazia não tem membros para distribuir
// @ts-expect-error nada é atribuível a never, nem sequer false
const v: Vazio = false;

type Cheio = SoTextoInteiro<never>; // true: never é atribuível a string
const cheio: Cheio = true;

console.log(a1, a2, b1, c1, cheio); // true false false true true

type TirarDaUniao<T, U> = T extends U ? never : T;
type SoEstes<T, U> = T extends U ? T : never;

type Estado = "rascunho" | "revisao" | "publicado" | "arquivado";

type Editaveis = TirarDaUniao<Estado, "publicado" | "arquivado">; // "rascunho" | "revisao"
type Finais = SoEstes<Estado, "publicado" | "arquivado">;         // "publicado" | "arquivado"

const e1: Editaveis = "rascunho";
const e2: Editaveis = "revisao";
// @ts-expect-error "publicado" foi removido da união
const e3: Editaveis = "publicado";
const f1: Finais = "publicado";

type SemNulos<T> = T extends null | undefined ? never : T;
type Nome = SemNulos<string | null | undefined>; // string
const nome: Nome = "Ana";

function primeiroEditavel(estados: readonly Estado[]): Editaveis | undefined {
  for (const estado of estados) {
    if (estado !== "publicado" && estado !== "arquivado") return estado;
  }
  return undefined;
}

console.log(e1, e2, f1, nome); // rascunho revisao publicado Ana
console.log(primeiroEditavel(["publicado", "revisao"])); // revisao
console.log(primeiroEditavel(["arquivado"])); // undefined

type NomeDoTipo<T> =
  T extends string ? "texto" :
  T extends number ? "numero" :
  T extends boolean ? "booleano" :
  T extends undefined ? "indefinido" :
  T extends null ? "nulo" :
  T extends (...args: never[]) => unknown ? "funcao" :
  T extends readonly unknown[] ? "lista" :
  "objeto";

const n1: NomeDoTipo<string> = "texto";
const n2: NomeDoTipo<number[]> = "lista";
const n3: NomeDoTipo<() => void> = "funcao";
const n4: NomeDoTipo<{ a: 1 }> = "objeto";
const n5: NomeDoTipo<null> = "nulo";

type Misto = NomeDoTipo<string | boolean>; // "texto" | "booleano"
const n6: Misto = "texto";
// @ts-expect-error a união só contém "texto" e "booleano"
const n7: Misto = "numero";

console.log(n1, n2, n3, n4, n5, n6); // texto lista funcao objeto nulo texto

type Repetido<T> = T extends string ? string[] : T extends number ? number[] : never;

function repetir<T extends string | number>(valor: T, vezes: number): Repetido<T> {
  // @ts-expect-error com T por resolver, Repetido<T> não aceita este array
  return new Array<T>(vezes).fill(valor);
}

function repetirComAsercao<T extends string | number>(valor: T, vezes: number): Repetido<T> {
  return new Array<T>(vezes).fill(valor) as unknown as Repetido<T>;
}

const letras = repetirComAsercao("a", 3); // letras: string[]
const numeros = repetirComAsercao(7, 2);  // numeros: number[]

console.log(letras);  // [ 'a', 'a', 'a' ]
console.log(numeros); // [ 7, 7 ]
console.log(letras.join("-")); // a-a-a

