type TirarDaUniao<T, U> = T extends U ? never : T;

type Secreta = "passwordHash" | "tokenInterno";
type Chave = "id" | "nome" | "email" | Secreta;
type ChavePublica = TirarDaUniao<Chave, Secreta>; // "id" | "nome" | "email"

function podeMostrar(chave: Chave): chave is ChavePublica {
  return chave !== "passwordHash" && chave !== "tokenInterno";
}

const chaves: Chave[] = ["id", "passwordHash", "email", "tokenInterno", "nome"];
const publicas: ChavePublica[] = chaves.filter(podeMostrar);

// @ts-expect-error "tokenInterno" já não pertence a ChavePublica
const invalida: ChavePublica = "tokenInterno";

console.log(publicas); // [ 'id', 'email', 'nome' ]

