type NomeDeTipo = "texto" | "numero" | "booleano";

type ValorDe<T> =
  T extends "texto" ? string :
  T extends "numero" ? number :
  T extends "booleano" ? boolean :
  never;

function converter<T extends NomeDeTipo>(tipo: T, bruto: string): ValorDe<T> {
  if (tipo === "numero") {
    const n = Number(bruto);
    if (Number.isNaN(n)) throw new Error("valor sem forma de número: " + bruto);
    return n as unknown as ValorDe<T>;
  }
  if (tipo === "booleano") {
    return (bruto === "true") as unknown as ValorDe<T>;
  }
  return bruto as unknown as ValorDe<T>;
}

const texto = converter("texto", "ola");        // texto: string
const numero = converter("numero", "42");       // numero: number
const booleano = converter("booleano", "true"); // booleano: boolean

console.log(texto.toUpperCase()); // OLA
console.log(numero + 1);          // 43
console.log(booleano === true);   // true

try {
  converter("numero", "abc");
} catch (erro) {
  console.log(erro instanceof Error ? erro.message : erro); // valor sem forma de número: abc
}
